	@Test
	void committedLmdbDeletionDurablyInvalidatesReadySynopsisBeforeCommit(@TempDir Path dataDirectory)
			throws Exception {
		Path frontierDirectory = dataDirectory.resolve(FRONTIER_DIRECTORY_NAME);
		createReadyGeneration(dataDirectory, frontierDirectory);

		LmdbStore deletingStore = open(dataDirectory);
		try {
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(deletingStore));
			try (NotifyingSailConnection connection = deletingStore.getConnection()) {
				connection.begin();
				connection.removeStatements(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
				assertEquals(FrontierSynopsisStatus.DIRTY_DELETION, frontierStatus(deletingStore),
						"the deletion commit must not leave the clean synopsis authoritative");
				assertTrue(Files.isRegularFile(frontierDirectory.resolve("dirty-deletion.bin")));
			}
		} finally {
			deletingStore.shutDown();
		}

		LmdbStore restarted = open(dataDirectory);
		try {
			assertEquals(FrontierSynopsisStatus.DIRTY_DELETION, frontierStatus(restarted));
		} finally {
			restarted.shutDown();
		}
	}

	@Test
	void committedLmdbInsertionPublishesExactAdditiveGeneration(@TempDir Path dataDirectory)
			throws Exception {
		Path frontierDirectory = dataDirectory.resolve(FRONTIER_DIRECTORY_NAME);

		LmdbStore insertingStore = open(dataDirectory);
		try {
			try (NotifyingSailConnection connection = insertingStore.getConnection()) {
				connection.begin();
				connection.addStatement(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.READY, insertingStore.rebuildFrontierSynopsis());
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(insertingStore));
			try (NotifyingSailConnection connection = insertingStore.getConnection()) {
				connection.begin();
				connection.addStatement(INSERTED_SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(insertingStore),
					"a committed insertion with a durable exact additive payload must remain authoritative");
			assertFalse(Files.exists(frontierDirectory.resolve("dirty-insertion.bin")),
					"the pre-commit insertion marker must clear only after manifest publication");
			FrontierManifest manifest = new FrontierManifestStore(frontierDirectory,
					NioFrontierFileOps.INSTANCE).load();
			assertEquals(1, manifest.insertPayloads().size());
			assertEquals(FrontierPayloadKind.INSERT, manifest.insertPayloads().get(0).kind());
			try (NotifyingSailConnection connection = insertingStore.getConnection()) {
				connection.begin();
				connection.addStatement(SECOND_INSERTED_SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(insertingStore));
			manifest = new FrontierManifestStore(frontierDirectory, NioFrontierFileOps.INSTANCE).load();
			assertEquals(2, manifest.insertPayloads().size());
			try (FrontierSnapshotSource snapshot = openSnapshot(insertingStore)) {
				FrontierSynopsisReadResult read = frontierService(insertingStore).scanSnapshot(
						snapshot.snapshotEpoch(),
						(direction, laneRole, laneIndex, explicit, databaseExact, centerId, predicateId, neighborId,
								contextId, weight, inclusionProbability, laneHash) -> {
						});
				assertEquals(FrontierSynopsisStatus.READY, read.status());
				assertEquals(24L, read.recordCount(),
						"three exact statements must compose across two directions and four lanes");
				assertTrue(read.databaseExact());
			}
		} finally {
			insertingStore.shutDown();
		}

		Files.write(frontierDirectory.resolve("dirty-insertion.bin"), ByteBuffer.allocate(2 * Integer.BYTES)
				.putInt(0x524a4644)
				.putInt(1)
				.array());
		LmdbStore restarted = open(dataDirectory);
		try {
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(restarted));
			assertFalse(Files.exists(frontierDirectory.resolve("dirty-insertion.bin")),
					"a crash after manifest publication must recover by validating the new epoch and payloads");
		} finally {
			restarted.shutDown();
		}
	}

	@Test
	void rolledBackInsertionRemovesOnlyItsPreCommitMarker(@TempDir Path dataDirectory) throws Exception {
		Path frontierDirectory = dataDirectory.resolve(FRONTIER_DIRECTORY_NAME);
		LmdbStore store = open(dataDirectory);
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(INSERTED_SUBJECT, PREDICATE, OBJECT);
				connection.rollback();
			}
			assertEquals(FrontierSynopsisStatus.READY, frontierStatus(store));
			assertFalse(Files.exists(frontierDirectory.resolve("dirty-insertion.bin")));
			assertTrue(new FrontierManifestStore(frontierDirectory, NioFrontierFileOps.INSTANCE)
					.load()
					.insertPayloads()
					.isEmpty());
		} finally {
			store.shutDown();
		}
	}

