	@Test
	void deletionDominatesBudgetExhaustedInsertChain(@TempDir Path dataDirectory) throws Exception {
		Path frontierDirectory = dataDirectory.resolve(FRONTIER_DIRECTORY_NAME);
		long baseButNotSecondGenerationBudget = FrontierPayloadBlockWriter.MINIMUM_BLOCK_BYTES
				+ 3L * FrontierSynopsisBuilder.RECORD_LONGS * Long.BYTES;
		LmdbStore store = open(dataDirectory, baseButNotSecondGenerationBudget);
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(INSERTED_SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.BUDGET_EXCEEDED, frontierStatus(store));
			assertTrue(Files.exists(frontierDirectory.resolve("dirty-insertion.bin")));

			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.removeStatements(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			assertEquals(FrontierSynopsisStatus.DIRTY_DELETION, frontierStatus(store));
			assertTrue(Files.exists(frontierDirectory.resolve("dirty-deletion.bin")));
			assertFalse(Files.exists(frontierDirectory.resolve("dirty-insertion.bin")));
		} finally {
			store.shutDown();
		}
	}

	private static void createReadyGeneration(Path dataDirectory, Path frontierDirectory) throws Exception {
		LmdbStore writer = open(dataDirectory);
		try {
			try (NotifyingSailConnection connection = writer.getConnection()) {
				connection.begin();
				connection.addStatement(SUBJECT, PREDICATE, OBJECT);
				connection.commit();
			}
			FrontierManifestIdentity identity;
			try (FrontierSnapshotSource snapshot = openSnapshot(writer)) {
				identity = identity(readStoreId(dataDirectory), snapshot.snapshotEpoch());
			}
			publishValidGeneration(frontierDirectory, identity);
		} finally {
			writer.shutDown();
		}
	}

	private static LmdbStore open(Path dataDirectory) {
		return open(dataDirectory, SYNOPSIS_BUDGET_BYTES);
	}

	private static LmdbStore open(Path dataDirectory, long synopsisBudgetBytes) {
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config(synopsisBudgetBytes));
		store.init();
		return store;
	}

	private static LmdbStoreConfig config(long synopsisBudgetBytes) {
		return new LmdbStoreConfig("spoc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(synopsisBudgetBytes);
	}

	private static UUID readStoreId(Path dataDirectory) throws Exception {
		Properties properties = new Properties();
		try (InputStream input = Files.newInputStream(dataDirectory.resolve(STORE_PROPERTIES_FILE))) {
			properties.load(input);
		}
		return UUID.fromString(properties.getProperty(STORE_ID_KEY));
	}

	private static FrontierSnapshotSource openSnapshot(LmdbStore store) throws Exception {
		Object backingStore = backingStore(store);
		Field tripleStoreField = backingStore.getClass().getDeclaredField("tripleStore");
		tripleStoreField.setAccessible(true);
		Object tripleStore = tripleStoreField.get(backingStore);
		Class<?> sourceType = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbFrontierSnapshotSource");
		Constructor<?> constructor = sourceType.getDeclaredConstructor(tripleStoreField.getType());
		constructor.setAccessible(true);
		try {
			return (FrontierSnapshotSource) constructor.newInstance(tripleStore);
		} catch (InvocationTargetException e) {
			return fail("opening the exact LMDB snapshot source failed", e.getCause());
		}
	}

	private static FrontierSynopsisStatus frontierStatus(LmdbStore store) throws Exception {
		Object backingStore = backingStore(store);
		Method status = backingStore.getClass().getDeclaredMethod("frontierSynopsisStatus");
		status.setAccessible(true);
		try {
			return (FrontierSynopsisStatus) status.invoke(backingStore);
		} catch (InvocationTargetException e) {
			return fail("reading Frontier synopsis status failed", e.getCause());
		}
	}

	private static LmdbFrontierSynopsisService frontierService(LmdbStore store) throws Exception {
		Object backingStore = backingStore(store);
		Field service = backingStore.getClass().getDeclaredField("frontierSynopsisService");
		service.setAccessible(true);
		return (LmdbFrontierSynopsisService) service.get(backingStore);
	}

	private static Object backingStore(LmdbStore store) throws Exception {
		Method accessor = LmdbStore.class.getDeclaredMethod("getBackingStore");
		accessor.setAccessible(true);
		return accessor.invoke(store);
	}

	private static FrontierManifestIdentity identity(UUID storeId, long snapshotEpoch) {
		return new FrontierManifestIdentity(
				storeId,
				snapshotEpoch,
				LmdbFrontierSynopsisService.SYNOPSIS_SCHEMA_VERSION,
				LmdbFrontierSynopsisService.HASH_VERSION,
				LmdbFrontierSynopsisService.SEED_SCHEDULE_VERSION,
				2,
				2,
				FrontierManifestIdentity.ALL_DIRECTIONS,
				FrontierManifestIdentity.ALL_LANE_ROLES,
				SYNOPSIS_BUDGET_BYTES);
	}

	private static void publishValidGeneration(Path frontierDirectory, FrontierManifestIdentity identity)
			throws Exception {
		Files.createDirectories(frontierDirectory);
		long generation = 97L;
		ByteArrayOutputStream encodedPayload = new ByteArrayOutputStream();
		FrontierPayloadBlockLimits limits = new FrontierPayloadBlockLimits(
				SYNOPSIS_BUDGET_BYTES,
				64 * 1024,
				1024,
				256,
				8);
		FrontierPayloadBlockWriter writer = new FrontierPayloadBlockWriter(
				encodedPayload, FrontierPayloadKind.BASE, generation, limits);
		writer.writeBlock(4, new long[] { 11L, 12L, 13L, 14L });
		FrontierPayloadDescriptor descriptor = writer.finish();
		FrontierFileOps fileOps = NioFrontierFileOps.INSTANCE;
		Path temporaryPayload = frontierDirectory.resolve(descriptor.fileName() + ".tmp");
		Path payload = frontierDirectory.resolve(descriptor.fileName());
		fileOps.writeAndForce(temporaryPayload, encodedPayload.toByteArray());
		fileOps.moveAtomically(temporaryPayload, payload);
		fileOps.forceDirectory(frontierDirectory);
		new FrontierManifestStore(frontierDirectory, fileOps)
				.publish(new FrontierManifest(generation, identity, descriptor));
	}
